contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function: attempt to call sendMoney with arbitrary target/value/data
    function run(address target, uint value, bytes calldata data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= value);

        // observe before-values
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        // call sendMoney as owner (this contract is owner)
        bool sendReverted;
        c.sendMoney(target, value, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            sendReverted = true;
        } else {
            sendReverted = false;
        }

        // observe after-values
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // General rule: regardless of success, sendMoney cannot increase depositsCount;
        // moreover, if the call succeeded then C's balance did not increase (it may decrease or stay same).
        assert(afterDeposits <= beforeDeposits && (sendReverted || afterBalance <= beforeBalance));
    }

    // allow receiving Ether when C sends back
    receive() external payable {}
}

